    x = marker_c - 8
    y = marker_r
    out[y][x] = 5

    # The narrow 4-pixel gutters separate 3x3 commands. Read the whole left
    # strip first, then the whole right strip, as the traced output demonstrates.
    commands = []
    for col in (0, 4):
        for top in range(0, h - 2, 4):
            tile = [g[r][c] for r in range(top, top + 3)
                    for c in range(col, col + 3)]
            ink = [v for v in tile if v != 0]
            if not ink:
                continue
            color = ink[0]
            # Template-specific movement: the glyph shape determines the
            # horizontal displacement, while its color is used for drawing.
            coords = {(i // 3, i % 3) for i, v in enumerate(tile) if v != 0}
            template = tuple(sorted(coords))
            if template == ((0, 0), (0, 1), (1, 0), (1, 2), (2, 1)):
                kind = 'A'
            elif template == ((0, 0), (0, 2), (1, 0), (1, 2), (2, 0), (2, 1), (2, 2)):
